// dce.js — LE DOSSIER ET LA LECTURE DES PIÈCES (13/10/2026, Ethan : « j'ai importé un dossier, ça me met juste le lien du zip, les pièces ne sont pas du tout traitées
// comme la maquette le montrait… dans Lecture je n'ai pas du tout le beau visuel avec la pièce ouverte que tu lis, que tu survoles et sur laquelle tu peux faire des
// commentaires et notes de lecture : j'ai vraiment besoin de ça »).
// · Dossier : un zip déposé est DÉBALLÉ (zip imbriqués compris) → une pièce par fichier, classée (CCTP, DPGF, CCAP, RC, AE, plans, profils, PPSPS…), gardée sur
//   l'appareil (IndexedDB) et envoyée au stockage serveur ; l'archive d'origine est gardée telle quelle ; versions (v2 d'une pièce) ; pièces texte (mail, alignement technique).
// · Lecture : la pièce s'ouvre à gauche (PDF via pdf.js — pages + couche texte —, Word, Excel, image, texte) ; on sélectionne un passage → note avec page, article détecté,
//   extrait, destinations (chiffrage / mémoire / risque / question MOE / info) ; les passages restent surlignés (couleur de la destination), survol note ↔ passage ;
//   notes à droite filtrées par destination. Points techniques (liste à remplir) → préremplissent le chiffrage (chiffrage.js : etudeFromPoints).
import {zipEntries,inflateBytes,inflate,xmlUnesc} from './xlsx.js';
import {UI,prixBase,chiffrageState,migratePoints} from './chiffrage.js';
import {sstTypes,raccTypes,DNS,joursChantier,dnVolume,isoDiam,foLookup,foParam} from './prix.js';
import {areaDN} from './hydro.js';
import {readOffice} from './formats.js';
import {formType,FORMS} from './docsoblig.js'; // 14/10 après-midi (lot D) : formulaires à remplir repérés dans le DCE (7 · Offre → Documents obligatoires)
let A=null;export function initDce(api){A=api;}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nb=(x,d)=>{x=+x||0;return x.toLocaleString('fr-FR',{maximumFractionDigits:d===undefined?0:d,minimumFractionDigits:d===undefined?0:d});};
const dFR=x=>x?new Date(x).toLocaleDateString('fr-FR'):'';const mo=b=>b>=1048576?(b/1048576).toFixed(1).replace('.',',')+' Mo':Math.max(1,Math.round(b/1024))+' Ko';
const num=v=>typeof v==='number'?v:(v===null||v===undefined||v===''?0:(isFinite(+v)?+v:0));
/* ═════════ 1 · PIÈCES : catégories, états ═════════ */
export const CATS=[['cctp','CCTP',/cctp|clauses?\s*tech|c\.c\.t\.p|prescriptions? tech/i],['dpgf','DPGF / BPU',/dpgf|bpu|bordereau|d\.p\.g\.f|d\.?q\.?e\b|estimatif|quantitatif/i],['ccap','CCAP',/ccap|clauses?\s*admin|c\.c\.a\.p/i],['rc','RC (règlement)',/(^|[^a-z])rc([^a-z]|$)|r[eè]glement.*consult|r\.c\./i],['ae','Acte d\'engagement',/(^|[^a-z])ae([^a-z]|$)|acte.*engagement|a\.e\./i],['plans','Plans',/plan|\.dwg$|\.dxf$|synoptique|trac[eé]|implantation/i],['profils','Profils en long',/profil/i],['ppsps','PPSPS / sécurité',/ppsps|pgc|s[eé]curit|coordination/i],['memoire','Mémoire technique (cadre)',/m[eé]moire|cadre.*r[eé]p|note.*m[eé]tho/i],['planning','Planning',/planning|calendrier/i],['courrier','Courrier · mail · alignement',/mail|courrier|question|r[eé]ponse|alignement|(^|[^a-z])pv([^a-z]|$)|compte.?rendu|pr[eé]cision/i],['devis','Devis · offre',/devis|offre/i],['facturation','Facturation',/factur|situation/i],['autre','Autre',/./]];
const LEGACY_CAT={'DCE · CCTP / règlement':'cctp','DCE · DPGF / BPU':'dpgf','DCE · plans':'plans','Devis / offre remise':'devis','Mémoire technique':'memoire','Courrier / échange client':'courrier','Marché / OS / avenant':'courrier','Facturation · tableau client':'facturation','DCE · archive d\'origine':'archive'};
export function catOf(d){if(d.archive)return 'archive';if(d.catKey&&CATS.some(c=>c[0]===d.catKey))return d.catKey;if(d.cat&&LEGACY_CAT[d.cat])return LEGACY_CAT[d.cat];return guessCat(d.name||'');}
export function guessCat(name,path){/* le dossier du zip d'abord (Plans/, Pièces écrites/…), puis le nom du fichier */const folders=String(path||'').split('/').slice(0,-1).reverse();for(const f of folders){const hit=CATS.find(c=>c[0]!=='autre'&&c[0]!=='courrier'&&c[2].test(f));if(hit)return hit[0];}
  const n=String(name||'').replace(/\.[a-z0-9]+$/i,'');const hit=CATS.find(c=>c[0]!=='autre'&&c[2].test(n));return hit?hit[0]:'autre';}
export const catLabel=k=>k==='archive'?'Archive d\'origine':((CATS.find(c=>c[0]===k)||[])[1]||k);
export const extOf=n=>(String(n||'').match(/\.([a-z0-9]+)$/i)||[,''])[1].toLowerCase();
export const kindOf=d=>{if(d.text!==undefined&&d.text!==null)return 'text';const e=extOf(d.name);return e==='pdf'?'pdf':['docx','docm','dotx','doc','dot','rtf','odt','msg'].includes(e)?'docx':['xlsx','xlsm'].includes(e)?'xlsx':['png','jpg','jpeg','gif','webp','bmp'].includes(e)?'img':['txt','csv','md'].includes(e)?'txt':'other';};
const ICON={pdf:'📄',docx:'📝',xlsx:'📊',img:'🖼',text:'✉',txt:'📃',other:'📎'};
const MIME={pdf:'application/pdf',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',xlsm:'application/vnd.ms-excel.sheet.macroEnabled.12',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',gif:'image/gif',webp:'image/webp',txt:'text/plain',csv:'text/csv',zip:'application/zip',dwg:'application/acad',dxf:'application/dxf'};
export const docsOf=a=>(a.dce||[]).filter(d=>!d.deleted);
export const liveDocs=a=>docsOf(a).filter(d=>!d.superseded);
const kvKey=d=>'trace:affdoc:'+d.id;
const newId=()=>'D'+Date.now().toString(36)+Math.random().toString(36).slice(2,5);
/* ═════════ 2 · DÉPÔT DE FICHIERS : zip déballé, pièces classées, stockage appareil + serveur ═════════ */
async function unzipFiles(buf,zipName,depth){const Z=await zipEntries(buf);const out=[];for(const name of Object.keys(Z)){if(/\/$/.test(name)||/(^|\/)(__MACOSX|\.DS_Store|Thumbs\.db)/i.test(name))continue;const e=Z[name];let bytes;try{bytes=await inflateBytes(e);}catch(err){console.warn('zip',name,err);continue;}const base=name.split('/').pop();
    if(/\.zip$/i.test(base)&&depth<2){try{const sub=await unzipFiles(bytes.buffer.slice(bytes.byteOffset,bytes.byteOffset+bytes.byteLength),base,depth+1);sub.forEach(s=>out.push(s));continue;}catch(err){console.warn('zip imbriqué',base,err);}}
    const ext=extOf(base);out.push({name:base,path:name,blob:new Blob([bytes],{type:MIME[ext]||'application/octet-stream'}),src:zipName});}
  return out;}
export async function dceFiles(num,files,ctx,opts){opts=opts||{};const a=A.affGet(num);if(!a||!ctx.canEdit)return;const say=t=>A.toast&&A.toast(t);const L=[...files];let n=0,sent=0,kept=0;const added=[];
  for(const f of L){if(f.size>120*1048576){say(f.name+' : plus de 120 Mo — dépose-le sur le Drive et colle le lien');continue;}
    const isZip=/\.(zip)$/i.test(f.name);let items=[];
    if(isZip){say('Déballage de '+f.name+'…');try{items=await unzipFiles(await f.arrayBuffer(),f.name,0);}catch(e){console.warn(e);say(f.name+' : archive illisible ('+(e.message||e)+')');}
      /* l'archive d'origine est gardée telle quelle (envoyée au stockage si possible) */let url=null;if(f.size<=50*1048576){try{url=A.sync&&A.sync.uploadDoc?await A.sync.uploadDoc('aff_'+String(num).replace(/[^A-Za-z0-9_-]/g,'_'),'dce',f.name,f):null;}catch(e){url=null;}}
      added.push({id:newId(),cat:'DCE · archive d\'origine',catKey:'archive',name:f.name,url:url||undefined,size:f.size,type:f.type||'application/zip',archive:true,note:url?'':'archive gardée sur cet appareil (non envoyée : hors connexion ou trop grosse)',by:A.userName(),at:new Date().toISOString()});if(!url){try{await A.kv.set(kvKey(added[added.length-1]),f);}catch(e){}}}
    else items=[{name:f.name,path:f.name,blob:f,src:''}];
    for(const it of items){const d={id:newId(),catKey:opts.catKey||guessCat(it.name,it.path),name:it.name,size:it.blob.size,type:it.blob.type||'',src:it.src||undefined,path:it.path!==it.name?it.path:undefined,by:A.userName(),at:new Date().toISOString()};if(opts.replaces){d.replaces=opts.replaces.id;d.version=(opts.replaces.version||1)+1;d.catKey=catOf(opts.replaces);}
      let ok=false;try{ok=await A.kv.set(kvKey(d),it.blob);}catch(e){ok=false;}if(ok){d.local=true;kept++;}
      if(it.blob.size<=50*1048576){try{const url=A.sync&&A.sync.uploadDoc?await A.sync.uploadDoc('aff_'+String(num).replace(/[^A-Za-z0-9_-]/g,'_'),'dce',it.name,it.blob):null;if(url){d.url=url;sent++;}}catch(e){}}
      if(!d.url&&!d.local)d.note='fichier ni envoyé ni gardé : redépose-le ou colle un lien';added.push(d);n++;}}
  if(!added.length){if(ctx.render)ctx.render();return;}
  const cur=A.affGet(num);let dce=(cur.dce||[]).concat(added);if(opts.replaces){const nv=added.find(d=>d.replaces===opts.replaces.id);if(nv)dce=dce.map(d=>d.id===opts.replaces.id?Object.assign({},d,{superseded:nv.id}):d);}
  A.affSet(num,{dce});say(n+' pièce'+(n>1?'s':'')+' ajoutée'+(n>1?'s':'')+(sent?' · '+sent+' envoyée'+(sent>1?'s':'')+' au serveur':'')+(kept?' · '+kept+' gardée'+(kept>1?'s':'')+' sur cet appareil':''));
  if(opts.open&&added.length){DS.doc=added[added.length-1].id;}if(ctx.render)ctx.render();}
/* fichier d'une pièce : copie de l'appareil, sinon téléchargement depuis le stockage (puis gardé sur l'appareil) */
export async function docBlob(d){try{const b=await A.kv.get(kvKey(d));if(b instanceof Blob)return b;}catch(e){}
  if(d.url){try{const r=await fetch(d.url);if(r.ok){const b=await r.blob();try{await A.kv.set(kvKey(d),b);}catch(e){}return b;}}catch(e){console.warn('docBlob',e);}}
  return null;}
/* ═════════ 3 · DOSSIER : la liste des pièces ═════════ */
const DS={doc:null,dest:'',all:false,showOld:false,zoom:{},nq:'',open:{},allOpen:false,full:false,flash:null};
export const dceState=()=>DS;
export function dossierDceHTML(a,canEdit,ctx){const docs=docsOf(a);const live=docs.filter(d=>!d.superseded&&!d.archive);const archives=docs.filter(d=>d.archive);const old=docs.filter(d=>d.superseded);
  const groups=CATS.map(c=>[c[0],c[1],live.filter(d=>catOf(d)===c[0])]).filter(g=>g[2].length);
  const row=d=>{const k=kindOf(d);const vTag=d.version?`<span class="eq-tag ok" title="Version ${d.version}${d.replaces?' — remplace une version précédente':''}">v${d.version}</span> `:'';const where=d.text!==undefined?'':d.url?'<span class="eq-tag" title="Au stockage serveur">☁</span>':d.local?'<span class="eq-tag" title="Sur cet appareil seulement (hors connexion au dépôt) — redépose-le connecté pour le partager">📱</span>':'<span class="eq-tag warn">lien manquant</span>';
    const ft=formType(d);const fTag=ft?`<span class="eq-tag" style="background:#fff4d6;color:#7a5200" title="Formulaire à remplir (${esc((FORMS.find(f=>f[0]===ft)||[])[1]||'')}) : 7 · Offre → Documents obligatoires pour déposer la version complétée">📝 à remplir</span> `:d.ver?`<span class="eq-tag" title="Écrit officiel rattaché à l'historique des versions du chiffrage">📨 v${esc(d.ver.v)}</span> `:''; /* 14/10 après-midi (lot D) */
    return `<div class="cm-piece cm-dp"><span class="cm-dpi">${ICON[k]||'📎'}</span><span class="tx"><b>${vTag}${fTag}${esc(d.name)}</b><small>${d.size?mo(d.size)+' · ':''}${d.src?'depuis '+esc(d.src)+' · ':''}${esc(d.by||'')} · ${dFR(d.at)}${(d.notes||[]).length?' · <b>'+(d.notes||[]).length+' note'+((d.notes||[]).length>1?'s':'')+'</b>':''}${d.note?' · <span style="color:#7a5200">'+esc(d.note)+'</span>':''}</small></span>${where}
      ${canEdit?`<select class="f cm-dpcat" data-afdoc="cat|${esc(d.id)}" title="Catégorie">${CATS.map(c=>`<option value="${c[0]}"${catOf(d)===c[0]?' selected':''}>${esc(c[1])}</option>`).join('')}</select>`:''}
      <span class="eq-acts" style="margin:0"><button class="btn sm" data-act="af" data-v="dcopen|${esc(d.id)}" title="Ouvrir dans Lecture">📖 Lire</button>${d.url?`<a class="btn sm" href="${esc(d.url)}" target="_blank" rel="noopener" title="Ouvrir le fichier">⤓</a>`:''}${canEdit?`<label class="btn sm" title="Déposer une nouvelle version (v${(d.version||1)+1}) : l'ancienne reste, ses notes aussi">⇪ v${(d.version||1)+1}<input type="file" data-afdoc="ver|${esc(d.id)}" style="display:none"></label><button class="btn sm" data-act="af" data-v="dcerm|${esc(d.id)}" style="color:#9b2c22">✕</button>`:''}</span></div>`;};
  return `<div class="card"><h3>Pièces du dossier <span class="hint">· ${live.length} pièce${live.length>1?'s':''}${old.length?' · '+old.length+' ancienne'+(old.length>1?'s':'')+' version'+(old.length>1?'s':''):''}${archives.length?' · '+archives.length+' archive'+(archives.length>1?'s':''):''}</span></h3>
    ${canEdit?`<div class="cm-drop"><label class="btn primary">📎 Déposer le DCE (zip) ou des pièces<input type="file" data-affile="${esc(a.num)}" style="display:none" multiple></label><button class="btn" data-act="af" data-v="dctext|">✉ Mail · précision · alignement technique</button><span class="hint">Un zip est déballé : une pièce par fichier, classée (CCTP, DPGF, RC, plans…), gardée sur cet appareil et envoyée au serveur ; l'archive d'origine est gardée telle quelle.</span></div>
    <details class="cm-linkform"><summary class="dim" style="cursor:pointer;font-size:12px;min-height:34px;display:flex;align-items:center">🔗 Ajouter une pièce par lien (Drive, SharePoint) ou une référence</summary><div class="row" style="display:flex;gap:6px;flex-wrap:wrap;margin-top:4px"><div style="flex:1;min-width:140px"><label class="f">Catégorie</label><select class="f" id="afd-cat">${CATS.map(c=>`<option value="${c[0]}">${esc(c[1])}</option>`).join('')}</select></div><div style="flex:2;min-width:160px"><label class="f">Nom</label><input class="f" id="afd-name" placeholder="ex. Plans DWG (Drive)"></div><div style="flex:2;min-width:160px"><label class="f">Lien</label><input class="f" id="afd-url" placeholder="https://…"></div><div style="flex:1;min-width:120px"><label class="f">Note</label><input class="f" id="afd-note"></div></div><div class="eq-acts" style="margin-top:6px"><button class="btn" data-act="af" data-v="dceadd|">Ajouter la pièce</button></div></details>`:''}
    ${groups.length?groups.map(([k,l,L])=>`<div class="cm-dgrp"><div class="eq-lab">${esc(l)} · ${L.length}</div>${L.map(row).join('')}</div>`).join(''):'<div class="eq-s">Aucune pièce pour l\'instant.</div>'}
    ${old.length?`<details style="margin-top:8px"><summary class="dim" style="cursor:pointer;font-size:12px;min-height:34px;display:flex;align-items:center">Anciennes versions · ${old.length}</summary>${old.map(row).join('')}</details>`:''}
    ${archives.length?`<div class="eq-lab" style="margin-top:8px">Archives d'origine</div>${archives.map(d=>`<div class="cm-piece cm-dp"><span class="cm-dpi">🗜</span><span class="tx"><b>${esc(d.name)}</b><small>${d.size?mo(d.size)+' · ':''}${esc(d.by||'')} · ${dFR(d.at)}${d.note?' · '+esc(d.note):''}</small></span>${d.url?`<a class="btn sm" href="${esc(d.url)}" target="_blank" rel="noopener">⤓</a>`:''}${canEdit?`<button class="btn sm" data-act="af" data-v="dcerm|${esc(d.id)}" style="color:#9b2c22">✕</button>`:''}</div>`).join('')}`:''}</div>`;}
function textPieceModal(a,ctx,d){const isNew=!d;d=d||{};A.openModal(`<h3 style="margin-top:0">${isNew?'Mail · précision · alignement technique':'Modifier la pièce'}</h3><div class="hint" style="margin:0 0 6px">Un mail du MOE qui précise un point, un compte rendu d'alignement technique, une réponse aux questions : collé ici, il devient une pièce du dossier, lisible et annotable comme les autres.</div>
    <label class="f">Titre</label><input class="f" id="dt-name" value="${esc(d.name||'')}" placeholder="ex. Mail MOE 15/10 — précision série 3"><div class="row" style="display:flex;gap:6px"><div style="flex:1"><label class="f">Date</label><input class="f" id="dt-date" type="date" value="${esc(d.date||new Date().toISOString().slice(0,10))}"></div><div style="flex:1"><label class="f">De</label><input class="f" id="dt-from" value="${esc(d.from||'')}" placeholder="MOE, MOA, fournisseur…"></div></div>
    <label class="f">Texte</label><textarea class="f" id="dt-text" style="min-height:160px" placeholder="Colle le mail ou le compte rendu…">${esc(d.text||'')}</textarea>
    <div class="actions" style="margin-top:8px"><button class="btn primary block" id="dt-ok">${isNew?'Ajouter la pièce':'Enregistrer'}</button><button class="btn block" data-close>Annuler</button></div>`);
  document.getElementById('dt-ok').onclick=()=>{const g=id=>(document.getElementById(id)||{}).value||'';const name=g('dt-name').trim();const text=g('dt-text');if(!name||!text.trim()){A.toast('Un titre et le texte');return;}
    const cur=A.affGet(a.num);const piece=Object.assign({},isNew?{id:newId(),catKey:'courrier',by:A.userName(),at:new Date().toISOString()}:d,{name,date:g('dt-date'),from:g('dt-from').trim(),text,size:text.length});
    A.affSet(a.num,{dce:isNew?(cur.dce||[]).concat([piece]):(cur.dce||[]).map(x=>x.id===d.id?piece:x)});A.closeModal();A.toast(isNew?'Pièce ajoutée au dossier':'Pièce modifiée');if(ctx.render)ctx.render();};}
function linkModal(a,ctx){A.openModal(`<h3 style="margin-top:0">Pièce par lien</h3><label class="f">Nom</label><input class="f" id="dl-name" placeholder="ex. Plans DWG (Drive)"><label class="f">Lien</label><input class="f" id="dl-url" placeholder="https://…"><label class="f">Catégorie</label><select class="f" id="dl-cat">${CATS.map(c=>`<option value="${c[0]}">${esc(c[1])}</option>`).join('')}</select><div class="actions" style="margin-top:8px"><button class="btn primary block" id="dl-ok">Ajouter</button><button class="btn block" data-close>Annuler</button></div>`);
  document.getElementById('dl-ok').onclick=()=>{const g=id=>(document.getElementById(id)||{}).value||'';if(!g('dl-name').trim()){A.toast('Le nom');return;}const cur=A.affGet(a.num);A.affSet(a.num,{dce:(cur.dce||[]).concat([{id:newId(),catKey:g('dl-cat'),name:g('dl-name').trim(),url:g('dl-url').trim()||undefined,by:A.userName(),at:new Date().toISOString()}])});A.closeModal();if(ctx.render)ctx.render();};}
/* ═════════ 4 · LECTURE : pièces en onglets, visionneuse à gauche, notes à droite ═════════
   v3 (13/10/2026, retours d'Ethan sur la v2 : « optimiser l'écran pour que les documents soient bien visibles, bien ouverts — c'est en HAUTEUR qu'il faut
   travailler ; qu'on puisse les RETOURNER (plan PDF) ; une section pour mettre des notes sur un document qu'on n'ouvre pas (DWG trop lourd) et le
   TÉLÉCHARGER ; il ne lit pas les Word ; la note qu'on met en surlignant doit être mise en avant, comme TITRE ; les notes allongent la file → un
   DÉROULANT ; RECHERCHE dans les notes et dans le document ; mettre le document sur un 2e / 3e ÉCRAN et pouvoir l'annoter quand même »).
   · visionneuse à hauteur d'écran, mode plein écran (pièce + notes), pleine largeur ↔ page entière, zoom NET (pages redessinées), rotation par pièce
     (gardée sur la pièce, les surlignages suivent), outil ▭ « encadrer une zone » (plans, scans sans texte), recherche dans la pièce (Ctrl+F) ;
   · Word .docx / .doc / .rtf / .odt et mails Outlook .msg lus (formats.js) ; surlignages des pièces texte ANCRÉS au texte (ils suivent la mise en page) ;
   · pièce illisible (DWG…) : la raison en clair, ⤓ télécharger, note avec repère (folio, zone, rue) ;
   · ⧉ fenêtre séparée (2e écran) : la pièce s'y ouvre, on y surligne / encadre, les notes arrivent dans l'appli ;
   · notes : TITRE = la note tapée, déroulantes, recherche, ✎ modifier, tri dans l'ordre de la pièce. */
export const DEST_ORDER=['chiffrage','memoire','risque','question','info'];
const noteDests=n=>Array.isArray(n.dests)&&n.dests.length?n.dests:(n.dest?[n.dest]:[]);
const DEST_LAB={chiffrage:'→ chiffrage',memoire:'→ mémoire technique',risque:'⚠ risque / point de vigilance',question:'? question MOE',info:'ℹ info'};
const DEST_ICO={chiffrage:'€',memoire:'M',risque:'!',question:'?',info:'i'};
const FILT_LAB={chiffrage:'Chiffrage',memoire:'Mémoire',risque:'Risque',question:'Question MOE',info:'Info'};const filtChip=(k,c)=>k?`<span class="cm-nd ${k}">${DEST_ICO[k]}</span> ${FILT_LAB[k]} · ${c}`:'Toutes · '+c;
/* repli « sans accents, minuscules » de MÊME longueur que le texte (les positions trouvées restent valables dans le texte d'origine) */
export const fold=s=>String(s??'').replace(/[\s\S]/g,c=>{const d=c.normalize('NFD');const b=((d.length?d[0]:c)||c).toLowerCase();return b.length===1?b:c;}).replace(/\s/g,' ');
export const noteTitle=n=>String(n.texte||'').trim()||(n.extrait?'« '+n.extrait+' »':'')||n.ref||'Note';
