export const notesAll=a=>docsOf(a).flatMap(d=>(d.notes||[]).map((n,i)=>Object.assign({_doc:d.name,_docId:d.id,_i:i,_old:!!d.superseded,_v:d.version},n)));
function notesListHTML(a,shown,canEdit,cur){if(!shown.length)return DS.nq?`<div class="eq-s" style="margin-top:6px">Aucune note ne contient « ${esc(DS.nq)} ».</div>`:'<div class="eq-s" style="margin-top:6px">Pas encore de note de lecture sur cette pièce.</div>';
  const many=DS.all||!cur;return shown.map(n=>{const key=n._docId+'|'+n._i;const ds=noteDests(n);const open=DS.allOpen||!!DS.open[key]||DS.flash===key;const nav=(n.rects&&n.rects.length)||n.anchor;const done=Object.keys(n.done||{}).filter(k=>n.done[k]);
    return `<details class="af-note cm-n ${esc(ds[0]||'')}${DS.flash===key?' flash':''}" data-n="${esc(key)}"${open?' open':''}${open&&!DS.open[key]?' data-auto="1"':''}><summary><span class="cm-nt">${markQ(noteTitle(n),DS.nq)}</span><span class="cm-nm">${ds.map(x=>`<span class="cm-nd ${x}" title="${esc(DEST_LAB[x]||x)}">${DEST_ICO[x]||'·'}</span>`).join('')}${n.ref?` <b>${markQ(n.ref,DS.nq)}</b>`:''}${done.length?` · <span style="color:#15673a">✓ pris en compte</span>`:''}${many?` · ${esc(n._doc)}`:''}${n._old?' · v'+(n._v||1)+' (ancienne)':''}</span></summary>
      <div class="cm-nb">${n.extrait&&String(n.texte||'').trim()?`<div class="cm-nx">« ${markQ(n.extrait,DS.nq)} »</div>`:''}<span class="cm-tags">${ds.map(x=>`<span class="eq-tag ${x}">${DEST_LAB[x]||x}</span>`).join('')}</span><div class="dim" style="font-size:11px;margin-top:2px">${esc(n._doc)} · ${esc(n.by||'')}${n.at?' · '+dFR(n.at):''}${n.editedAt?' · modifiée':''}</div>
        <div class="eq-acts" style="margin-top:4px">${nav?`<button class="btn sm cm-ngo" data-act="af" data-v="dcgo|${esc(n._docId)}|${n._i}" title="Aller au passage dans la pièce">↗ Aller au passage</button>`:''}${canEdit?`<button class="btn sm" data-act="af" data-v="dcenoteed|${esc(n._docId)}|${n._i}">✎ Modifier</button><button class="btn sm" data-act="af" data-v="dcenoterm|${esc(n._docId)}|${n._i}" title="Retirer la note" style="color:#9b2c22">✕</button>`:''}</div></div></details>`;}).join('');}
/* modifier une note : son titre (la note), son repère, ses destinations */
function noteEditModal(a,docId,i){const d=docsOf(a).find(x=>x.id===docId);const n=d&&(d.notes||[])[i];if(!n)return;const ds=noteDests(n);
  A.openModal(`<h3 style="margin-top:0">Modifier la note <span class="hint">· ${esc(d.name)}</span></h3>${n.extrait?`<div class="cm-pop-x" style="max-height:none">« ${esc(n.extrait)} »</div>`:''}<label class="f">Note (titre)</label><input class="f" id="ne-txt" value="${esc(n.texte||'')}" placeholder="ex. Prévoir contrôle externe"><label class="f">Repère (page, article, folio, zone…)</label><input class="f" id="ne-ref" value="${esc(n.ref||'')}"><label class="f">Pour</label><div class="cm-pop-d" id="ne-dests">${DEST_ORDER.map(k=>`<button type="button" class="chip cm-pd ${k}${ds.includes(k)?' on':''}" data-k="${k}">${DEST_LAB[k]}</button>`).join('')}</div><div class="actions" style="margin-top:8px"><button class="btn primary block" id="ne-ok">Enregistrer</button><button class="btn block" data-close>Annuler</button></div>`);
  document.querySelectorAll('#ne-dests .cm-pd').forEach(b=>b.onclick=()=>b.classList.toggle('on'));
  document.getElementById('ne-ok').onclick=()=>{const dests=[...document.querySelectorAll('#ne-dests .cm-pd.on')].map(b=>b.dataset.k);if(!dests.length){A.toast('Coche au moins une destination');return;}const g=id=>(document.getElementById(id)||{}).value||'';const cur=A.affGet(a.num);
    A.affSet(a.num,{dce:(cur.dce||[]).map(x=>x.id!==docId?x:Object.assign({},x,{notes:(x.notes||[]).map((m,j)=>j!==i?m:Object.assign({},m,{texte:g('ne-txt').trim(),ref:g('ne-ref').trim(),dests,dest:dests[0],editedAt:new Date().toISOString(),editedBy:A.userName()}))}))});A.closeModal();A.toast('Note modifiée');refreshNotes();};}
/* ═════════ 5 · VISIONNEUSE (montée après le rendu, gardée en cache d'une vue à l'autre ; une 2e instance possible dans la fenêtre séparée) ═════════ */
const LV={cache:{},order:[],mounted:null,a:null,ctx:null,popup:null};
const TEXTK={text:1,docx:1,txt:1,xlsx:1};const isTextK=v=>!!TEXTK[v.kind];
const canEditNow=()=>!!(LV.ctx&&LV.ctx.canEdit);
const curAff=()=>LV.a?(A.affGet(LV.a.num)||LV.a):null;
