function focusNote(key){const el=document.querySelector(`#cm-lnotes .cm-n[data-n="${key}"]`);if(!el)return;el.open=true;DS.open[key]=true;const side=el.closest('.cm-lside');if(side&&side.scrollHeight>side.clientHeight+2){const r=el.getBoundingClientRect(),s2=side.getBoundingClientRect();side.scrollTo({top:Math.max(0,side.scrollTop+(r.top-s2.top)-(side.clientHeight-r.height)/2),behavior:'smooth'});}else el.scrollIntoView({block:'nearest',behavior:'smooth'});el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),1200);}
