  const jours=pt.d0&&pt.d1?(JC.ouvres?`<div class="cm-jours">📅 <b>${JC.ouvres} jours ouvrés</b> (lundi → vendredi) · ${JC.cal} j calendaires${fer.length?` · <span style="color:#7a5200">férié${fer.length>1?'s':''} : ${fer.join(', ')} (compté${fer.length>1?'s':''}, à toi de voir)</span>`:''}${bv.length?` · location base vie : <b>${JC.ouvres} j</b> pour ${bv.map(x=>x[1]).join(', ')} — à valider ou corriger dans le chiffrage`:' · coche la base vie ci-dessous : ce sera la durée de location proposée'}</div>`:'<div class="cm-jours" style="color:#9b2c22">La fin est avant le début.</div>'):'';
