  const sstCols=[['type','Type','sel',sstT],['dn','DN','dn'],['qty','Paires','n']];const sstBody=rows('sst',sstCols,'type de vanne')+(((pt.sst||{}).rows||[]).some(r=>r.type==='autre')?`<div class="cm-sst-autre">${((pt.sst||{}).rows||[]).map((r,i)=>r.type==='autre'?`<div class="ch-pair"><small>Ligne ${i+1} · autre :</small>${IN(p+'sst.rows.'+i+'.des',r.des,{type:'text',ro,ph:'désignation (ex. vanne motorisée PN25)'})}${IN(p+'sst.rows.'+i+'.pu',r.pu,{ro,cls:'ch-n',ph:'€ / paire'})}<small>€ / paire</small></div>`:'').join('')}</div>`:'')+(base?'':'<div class="hint" style="margin-top:4px">Les 9 typologies du classeur ; leurs prix viennent de la base de prix (Chiffrage → Base de prix).</div>');
